            recent = history[-25:]
            opp_recent_c = sum(1 for a in recent if a[1] == 'C')
            my_recent = sum(1 for a in recent if a[0] == 'C')
            if opp_recent_c >= 22:
                return 'C'
            if opp_recent_c <= 3:
                return 'D'
            if opp_recent_c >= 15 and my_recent >= 15:
